from common import *
P=R/'projects/game-math-rotation-conversions-v2';H=P/'production/concept-fit-v2';T=read(H/'timeline.json');D=P/'publishing/revisions/concept-fit-v2';D.mkdir(parents=True,exist_ok=True)
en=['Check whether different numbers describe one orientation','Conventions before conversion formulas','Construction view and a fixed orientation','Components of an object-attached axis','Worked atan2 and hypot examples','Euler angles and rotation matrices','Read the same three axes from a quaternion','Constructing matrix columns from a quaternion','Input axes and matrix columns','Recording the same orientation differently','Comparing two axes of a fixed orientation','Avoid unstable division when extracting rotation','Matrix to quaternion at180 degrees','Representation change versus an added rotation','Connecting Euler angles and quaternions','Fixed object, moving camera','Checking the same orientation with three axes','Missing information in axis-angle recovery','Zero rotation and half-turn axis-angle cases','Twist cannot be recovered from one direction','Do the converted values produce the same direction?','Intermediate orientations and round-trip checks','Rotate a vector and rotate it back','Compare results for matching input axes','Conventions and verification belong together','From rotated objects to lines and boundaries']
assert len(en)==len(T['scenes'])
def stamp(t):n=int(t);return f'{n//60:02}:{n%60:02}'
for lang in ['ko','en']:
 old=(P/f'publishing/upload-description.{lang}.txt').read_text(encoding='utf8');footer='🎮'+old.split('🎮',1)[1]
 intro='물체는 그대로 두고 그 자세를 적는 형식만 바꾸면 무엇이 같아야 할까요? 조립 화면의 변화와 물체 자세를 구분한 뒤, 오일러 각·회전 행렬·쿼터니언·축과 각의 변환을 기존 강의 순서대로 검산합니다.' if lang=='ko' else 'What must stay the same when an object stays fixed and only its orientation representation changes? Distinguish viewport changes from object orientation, then verify conversions among Euler angles, rotation matrices, quaternions and axis-angle in the original lesson order.'
 note='실제 게임 화면과 자체 계산 모형은 구분해 표시합니다. 정확한 축과 숫자는 모형에서 정한 값이며 게임 내부 측정값이 아닙니다. 별도 배경음악은 추가하지 않았습니다.' if lang=='ko' else 'Actual game footage and our mathematical models are labeled separately. Exact axes and numbers are defined in the models, not measured inside the game. No separate background-music track was added.'
 chapters='\n'.join(stamp(0 if i==0 else s['start'])+' '+(s['title'] if lang=='ko' else en[i]) for i,s in enumerate(T['scenes']))
 credits='\n\n'+('게임 화면 출처·권리' if lang=='ko' else 'Gameplay sources and rights')+'\nBesiege — Spiderling Studios. Construction footage used with transformative explanation; original video and publisher links retained.\nhttps://www.youtube.com/watch?v=uWKEJ92486U\nhttp://multiverse.spiderlinggames.co.uk/\n'
 (D/f'upload-description.{lang}.txt').write_text(intro+'\n\n'+note+'\n\n'+('챕터' if lang=='ko' else 'Chapters')+'\n'+chapters+'\n'+stamp(T['seconds']-10)+' '+('멤버십 감사와 코칭 안내' if lang=='ko' else 'Membership thanks and programming coaching')+'\n\n'+footer.rstrip()+credits,encoding='utf8')
save(H/'description-drafts.json',dict(status='local drafts only',files=[dict(path=rel(x),sha256=sha(x)) for x in D.glob('*.txt')],creditsAtBottom=True,uploadAuthorized=False))
